import{_ as t,c as l,j as e,a as n,o as r}from"./chunks/framework.CqbvlPrP.js";const m=JSON.parse('{"title":"交易中的亏损如何处理？","description":"","frontmatter":{},"headers":[],"relativePath":"stock/交易认知/交易中的亏损如何处理.md","filePath":"stock/交易认知/交易中的亏损如何处理.md"}'),o={name:"stock/交易认知/交易中的亏损如何处理.md"};function s(_,a,c,p,d,i){return r(),l("div",null,a[0]||(a[0]=[e("h1",{id:"交易中的亏损如何处理",tabindex:"-1"},[n("交易中的亏损如何处理？ "),e("a",{class:"header-anchor",href:"#交易中的亏损如何处理","aria-label":'Permalink to "交易中的亏损如何处理？"'},"​")],-1),e("p",null,"小仓位+右侧+止损，首次开仓就这么搞，直到吃上一个多头波段",-1),e("p",null,"波段结束留一手等底部区域同样还是买右侧+止损，这时候因为有一定的浮盈，所以仓位自然就可以适当的放大，用浮盈部位来对冲掉止损，最好留出几次止损的机会，直到吃到又一个多头波段",-1),e("p",null,"就这么反复的玩，积累到一定的浮盈其实开仓就越来越简单了，完全没有心理压力，也不太可能亏损，而且个股最好定一个仓位上限，不是每次波段底部都需要额外加仓，做到后面可能只需要把利润仓位回补就够了，这样这只标的这辈子大概你怎么玩都不会亏损",-1),e("p",null,"反正核心就这么几个点，第一：始终坚持按浮盈来决定仓位，而不是根据行情大小的预测来决定，因为你早晚会预测错，重仓被止损对账户来说损耗很大，尤其胜率一般的话就更加严重，做交易最重要的不是要多快，而是要稳，宁愿不赚也不要大亏，控制住回撤放在第一位，不要觉得这样慢，你只要一轮一轮稳稳的把该吃的波段吃到，仓位自然就能慢慢做大，要搞清楚一个点，交易不是只做一年两年，理论上如果你能稳定盈利的话，是可以一直做到死为止，所以不要怕错过了眼前的大行情，人生几十年这种日线波段几十个都有，根本不怕错过，前期慢那都是为未来打基础，反正记住一点就是不要在任一时刻下无法管控风险的重注，这个是绝大多数人都容易犯的毛病，这也是无法稳定盈利的关键所在，只要你侥幸一次，就永远不可能跳出无法稳定盈利的梦魇",-1),e("p",null,"第二：个股要反复做，不要来回换，积累的浮盈不仅利于持仓心态，复利效应也不可小觑",-1),e("p",null,"第三：止损的目的不是为了止损，而是为了参与后面的波段行情，不能做到进攻一味的防守也只是钝刀割肉，而前面两点已经让你最小风险最大概率的做到这点，所以慢一点不值得吗",-1)]))}const f=t(o,[["render",s]]);export{m as __pageData,f as default};
